Here's a sample Javascript code that shows an interactive pie chart using Chart.js library:

```
<html>
<head>
	<title>Interactive Pie Chart</title>
	<script src="https://cdnjs.cloudflare.com/ajax/libs/Chart.js/2.9.3/Chart.min.js"></script>
	<style>
	canvas{
		-moz-user-select: none;
		-webkit-user-select: none;
		-ms-user-select: none;
	}
	</style>
</head>
<body>
	<div style="width: 75%; margin: 0 auto;">
		<canvas id="pie-chart"></canvas>
	</div>

	<script>
		window.onload = function() {
			var ctx = document.getElementById("pie-chart").getContext('2d');

			var data = {
				labels: [
					"25%",
					"30%",
					"15%",
					"10%",
					"20%",
					"10%"
				],
				datasets: [
					{
						data: [25, 30, 15, 10, 20, 10],
						backgroundColor: [
							"#FF6384",
							"#36A2EB",
							"#FFCE56",
							"#009688",
							"#FF5722",
							"#8BC34A"
						],
						hoverBackgroundColor: [
							"#FF6384",
							"#36A2EB",
							"#FFCE56",
							"#009688",
							"#FF5722",
							"#8BC34A"
						]
					}]
			};

			var options = {
				responsive: true,
				animation:{
					animateScale:true
				},
				tooltips:{
					mode: 'label'
				}
			};

			var chart = new Chart(ctx,{
				type: 'pie',
				data: data,
				options: options
			});

			// Hover effect
			var segments = chart.getDatasetMeta(0).data;

			// Add cursor style to pie chart segments
			canvas.style.cursor = 'pointer';

			// Animate segments of pie chart on hover
			for(var i=0; i<segments.length; i++) {
				segments[i]._savedBackgroundColor = segments[i]._model.backgroundColor;
				segments[i]._model.backgroundColor = segments[i]._model.backgroundColor.replace("A", "D");
			}

			canvas.addEventListener('mousemove', function(evt) {
				var activeSegment = chart.getElementAtEvent(evt)[0];

				if(activeSegment) {
					for(var i=0; i<segments.length; i++) {
						segments[i]._model.backgroundColor = segments[i]._savedBackgroundColor;
					}
					activeSegment._model.backgroundColor = activeSegment._model.backgroundColor.replace("D", "A");
					chart.render();
				}
			});
		};
	</script>

</body>
</html>
```

This code uses Chart.js library to create a pie chart with hover effect. The hover effect is achieved by changing the background color of the hovered segments.

